-- Owner 2026-11-05: "เริ่มเลย" (ASG) — ASG Aluminium Profile as an extruder, prices like SMS (170, wood grain 350; colours as printed: white, black, Sahara grey, wood grain). Weights printed kg/m. Bar length not printed, 6.4 m assumed. Typo codes SAG-* stored as ASG-*.
-- Parts: docs/catalogs/asg/asg.json. Generated by 2026-11-05-import-asg.gen.py + .config.json; refuses to run twice.
BEGIN;
DO $$ BEGIN IF EXISTS (SELECT 1 FROM alu_providers WHERE tenant_id = '1b9affc4-2136-4ed1-b168-a36e6624e743' AND (id = '7a4ebc0d-e184-523a-a423-6fa51753ab74' OR short_name = 'ASG')) THEN RAISE EXCEPTION 'already imported'; END IF; END $$;
DO $$ DECLARE a int; b int; c int; f int; e int; BEGIN
  SELECT count(*) INTO a FROM alu_series WHERE provider_id = '7a4ebc0d-e184-523a-a423-6fa51753ab74';
  SELECT count(*) INTO b FROM alu_profiles WHERE provider_id = '7a4ebc0d-e184-523a-a423-6fa51753ab74';
  SELECT count(*) INTO c FROM alu_series_profiles sp JOIN alu_series s ON s.id = sp.series_id WHERE s.provider_id = '7a4ebc0d-e184-523a-a423-6fa51753ab74';
  SELECT count(*) INTO f FROM alu_profiles WHERE provider_id = '7a4ebc0d-e184-523a-a423-6fa51753ab74' AND image_path IS NOT NULL;
  SELECT count(*) INTO e FROM alu_kg_prices WHERE provider_id = '7a4ebc0d-e184-523a-a423-6fa51753ab74';
  IF a <> 12 OR b <> 107 OR c <> 107 OR f <> 107 OR e <> 4 THEN
    RAISE EXCEPTION 'count mismatch: series % profiles % links % images % prices %', a, b, c, f, e; END IF;
END $$;
SELECT f.name family, s.name series, count(sp.id) profiles, (SELECT count(*) FROM alu_series_types st WHERE st.series_id = s.id) types FROM alu_series s JOIN alu_series_families f ON f.id = s.series_family_id LEFT JOIN alu_series_profiles sp ON sp.series_id = s.id WHERE s.provider_id = '7a4ebc0d-e184-523a-a423-6fa51753ab74' GROUP BY f.name, f.sort_order, s.id, s.name ORDER BY f.sort_order, s.name;
COMMIT;
